{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openProjects } from './projects.js';

const projects = openProjects(process.env.DB_PATH || './data/workboard.sqlite');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/task-filters.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/task-filters.js', import.meta.url))]],
  ['/search.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/search.js', import.meta.url))]],
  ['/dates.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/dates.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && request.method === 'GET') {
      return json(response, 200, projects.list());
    }
    if (path === '/api/projects' && request.method === 'POST') {
      const body = await readJson(request);
      if (typeof body?.name !== 'string' || !body.name.trim()) {
        return json(response, 400, { error: 'Project name is required' });
      }
      return json(response, 201, projects.create(body.name));
    }
    const tasksMatch = path.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*)(\/(?:title|priority|due-date|notes|move))?)?$/);
    if (tasksMatch) {
      const [, projectId, taskId, fieldPath] = tasksMatch;
      const project = projects.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (!taskId && request.method === 'GET') {
        return json(response, 200, projects.tasks.list(projectId));
      }
      if (project.archived && (request.method === 'POST' || request.method === 'PATCH')) {
        return json(response, 409, { error: 'Archived project cannot be changed' });
      }
      if (!taskId && request.method === 'POST') {
        const body = await readJson(request);
        if (typeof body?.title !== 'string' || !body.title.trim()) {
          return json(response, 400, { error: 'Task title is required' });
        }
        return json(response, 201, projects.tasks.create(projectId, body.title, project.default_task_priority));
      }
      if (taskId && request.method === 'PATCH') {
        const body = await readJson(request);
        if (fieldPath === '/move') {
          return json(response, 200, projects.tasks.move(projectId, taskId, body?.destination_project_id));
        }
        if (fieldPath === '/due-date') {
          const task = projects.tasks.setDueDate(projectId, taskId, body?.due_date);
          return task ? json(response, 200, task) : json(response, 404, { error: 'Task not found' });
        }
        if (fieldPath === '/notes') {
          const task = projects.tasks.setNotes(projectId, taskId, body?.notes);
          return task ? json(response, 200, task) : json(response, 404, { error: 'Task not found' });
        }
        if (fieldPath === '/priority') {
          const task = projects.tasks.setPriority(projectId, taskId, body?.priority);
          return task ? json(response, 200, task) : json(response, 404, { error: 'Task not found' });
        }
        if (fieldPath === '/title') {
          const task = projects.tasks.rename(projectId, taskId, body?.title);
          return task ? json(response, 200, task) : json(response, 404, { error: 'Task not found' });
        }
        if (typeof body?.completed !== 'boolean') {
          return json(response, 400, { error: 'Completion must be a boolean' });
        }
        const task = projects.tasks.setCompleted(projectId, taskId, body.completed);
        return task ? json(response, 200, task) : json(response, 404, { error: 'Task not found' });
      }
    }
    const defaultPriorityMatch = path.match(/^\/api\/projects\/([1-9]\d*)\/default-task-priority$/);
    if (request.method === 'PATCH' && defaultPriorityMatch) {
      const body = await readJson(request);
      const project = projects.setDefaultPriority(defaultPriorityMatch[1], body?.priority);
      return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
    }
    const renameMatch = path.match(/^\/api\/projects\/([1-9]\d*)\/name$/);
    if (request.method === 'PATCH' && renameMatch) {
      const body = await readJson(request);
      const project = projects.rename(renameMatch[1], body?.name);
      return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
    }
    const projectMatch = path.match(/^\/api\/projects\/([1-9]\d*)$/);
    if (request.method === 'PATCH' && projectMatch) {
      const body = await readJson(request);
      if (typeof body?.archived !== 'boolean') {
        return json(response, 400, { error: 'Archive state must be a boolean' });
      }
      const project = projects.setArchived(projectMatch[1], body.archived);
      return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
    }
    if (request.method === 'GET' && projectMatch) {
      const project = projects.get(projectMatch[1]);
      return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
    }
    const asset = assets.get(path) || (/^\/projects\/[1-9]\d*$/.test(path) ? assets.get('/') : null);
    if (request.method === 'GET' && asset) {
      response.writeHead(200, { 'Content-Type': asset[0] });
      return response.end(asset[1]);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    projects.close();
    process.exit(0);
  }));
}
import { normalizeDueDate } from './public/dates.js';

export { normalizeDueDate } from './public/dates.js';

export function createTaskStore(database) {
  database.exec(`
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
    database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'notes')) {
    database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
    // Legacy ID order becomes explicit order; moving never changes task identity.
    database.exec(`
      BEGIN IMMEDIATE;
      ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
      UPDATE tasks SET position = id;
      COMMIT;
    `);
  }
  // tasks.position is the current position; history reserves positions even while
  // tasks are elsewhere. Seed only missing history to preserve existing order.
  database.exec(`
    CREATE TABLE IF NOT EXISTS task_project_positions (
      task_id INTEGER NOT NULL REFERENCES tasks(id),
      project_id INTEGER NOT NULL REFERENCES projects(id),
      position INTEGER NOT NULL,
      PRIMARY KEY (task_id, project_id),
      UNIQUE (project_id, position)
    );
    INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
      SELECT id, project_id, position FROM tasks;
  `);
  const list = database.prepare('SELECT id, title, completed, priority, due_date, notes FROM tasks WHERE project_id = ? ORDER BY position, id');
  const get = database.prepare('SELECT id, title, completed, priority, due_date, notes FROM tasks WHERE project_id = ? AND id = ?');
  const insert = database.prepare(`INSERT INTO tasks (project_id, title, priority, position)
    VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = ?))`);
  const rememberCreatedPosition = database.prepare(`INSERT INTO task_project_positions (task_id, project_id, position)
    SELECT id, project_id, position FROM tasks WHERE id = ?`);
  const rememberDestinationPosition = database.prepare(`INSERT INTO task_project_positions (task_id, project_id, position)
    VALUES (?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = ?))
    ON CONFLICT (task_id, project_id) DO NOTHING`);
  const getProject = database.prepare('SELECT * FROM projects WHERE id = ?');
  const move = database.prepare(`UPDATE tasks SET project_id = ?,
    position = (SELECT position FROM task_project_positions WHERE project_id = ? AND task_id = ?)
    WHERE project_id = ? AND id = ?`);
  const update = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const updateTitle = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
  const updatePriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
  const updateDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
  const updateNotes = database.prepare('UPDATE tasks SET notes = ? WHERE project_id = ? AND id = ?');
  const taskValue = (row) => row ? { ...row, completed: Boolean(row.completed) } : undefined;
  function transaction(operation) {
    database.exec('BEGIN IMMEDIATE');
    try {
      const result = operation();
      database.exec('COMMIT');
      return result;
    } catch (error) {
      database.exec('ROLLBACK');
      throw error;
    }
  }

  return {
    list: (projectId) => list.all(projectId).map(taskValue),
    create(projectId, title, priority = 'Normal') {
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) throw new Error('Task title is required');
      return transaction(() => {
        const taskId = insert.run(projectId, trimmedTitle, priority, projectId).lastInsertRowid;
        rememberCreatedPosition.run(taskId);
        return taskValue(get.get(projectId, taskId));
      });
    },
    move(projectId, taskId, destinationProjectId) {
      const fail = (status, message) => {
        const error = new Error(message);
        error.status = status;
        throw error;
      };
      if (!Number.isSafeInteger(destinationProjectId) || destinationProjectId < 1) {
        fail(400, 'Destination project must be a valid project ID');
      }
      return transaction(() => {
        const source = getProject.get(projectId);
        const destination = getProject.get(destinationProjectId);
        if (!source || !destination) fail(404, 'Project not found');
        if (source.archived || destination.archived) fail(409, 'Archived projects cannot move tasks');
        if (source.id === destination.id) fail(400, 'Destination must be another project');
        if (!get.get(projectId, taskId)) fail(404, 'Task not found');
        rememberDestinationPosition.run(taskId, destinationProjectId, destinationProjectId);
        move.run(destinationProjectId, destinationProjectId, taskId, projectId, taskId);
        return taskValue(get.get(destinationProjectId, taskId));
      });
    },
    setCompleted(projectId, taskId, completed) {
      if (typeof completed !== 'boolean') throw new Error('Completion must be a boolean');
      update.run(Number(completed), projectId, taskId);
      return taskValue(get.get(projectId, taskId));
    },
    setDueDate(projectId, taskId, dueDate) {
      const date = normalizeDueDate(dueDate);
      updateDueDate.run(date, projectId, taskId);
      return taskValue(get.get(projectId, taskId));
    },
    setNotes(projectId, taskId, notes) {
      if (typeof notes !== 'string') {
        const error = new Error('Task notes must be text');
        error.status = 400;
        throw error;
      }
      updateNotes.run(notes, projectId, taskId);
      return taskValue(get.get(projectId, taskId));
    },
    setPriority(projectId, taskId, priority) {
      if (!['Low', 'Normal', 'High'].includes(priority)) {
        const error = new Error('Task priority must be Low, Normal, or High');
        error.status = 400;
        throw error;
      }
      updatePriority.run(priority, projectId, taskId);
      return taskValue(get.get(projectId, taskId));
    },
    rename(projectId, taskId, title) {
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) {
        const error = new Error('Task title is required');
        error.status = 400;
        throw error;
      }
      updateTitle.run(trimmedTitle, projectId, taskId);
      return taskValue(get.get(projectId, taskId));
    },
  };
}
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { createTaskStore } from './tasks.js';

export function openProjects(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec('PRAGMA foreign_keys = ON');
  database.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    )
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
    database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
  }
  const tasks = createTaskStore(database);
  const projectFields = `SELECT id, name, archived, default_task_priority,
    (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id) AS total_count,
    (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND completed = 1) AS completed_count
    FROM projects`;
  const list = database.prepare(`${projectFields} ORDER BY id`);
  const get = database.prepare(`${projectFields} WHERE id = ?`);
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const updateName = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
  const updateDefaultPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
  const projectValue = (row) => row ? { ...row, archived: Boolean(row.archived) } : undefined;

  return {
    tasks,
    list: () => list.all().map(projectValue),
    get: (id) => projectValue(get.get(id)),
    create(name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) throw new Error('Project name is required');
      return projectValue(get.get(insert.run(trimmedName).lastInsertRowid));
    },
    setArchived(id, archived) {
      if (typeof archived !== 'boolean') throw new Error('Archive state must be a boolean');
      updateArchive.run(Number(archived), id);
      return projectValue(get.get(id));
    },
    setDefaultPriority(id, priority) {
      if (!['Low', 'Normal', 'High'].includes(priority)) {
        const error = new Error('Default task priority must be Low, Normal, or High');
        error.status = 400;
        throw error;
      }
      const project = get.get(id);
      if (!project) return undefined;
      if (project.archived) {
        const error = new Error('Archived project cannot be changed');
        error.status = 409;
        throw error;
      }
      updateDefaultPriority.run(priority, id);
      return projectValue(get.get(id));
    },
    rename(id, name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        const error = new Error('Project name is required');
        error.status = 400;
        throw error;
      }
      const project = get.get(id);
      if (!project) return undefined;
      if (project.archived) {
        const error = new Error('Archived project cannot be changed');
        error.status = 409;
        throw error;
      }
      updateName.run(trimmedName, id);
      return projectValue(get.get(id));
    },
    close: () => database.close(),
  };
}

import { filterTasks, normalizeDueRange } from './task-filters.js';
import { filterProjects, normalizeSearchQuery } from './search.js';

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showError(container, message) {
  container.textContent = message;
  container.hidden = false;
}

function renderRename(project) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Rename project');
  section.innerHTML = `
    <form>
      <label for="new-project-name">New project name</label>
      <div class="create-controls">
        <input id="new-project-name" type="text" autocomplete="off">
        <button type="submit">Rename project</button>
      </div>
    </form>
    <p role="alert" hidden></p>
  `;
  const form = section.querySelector('form');
  const input = form.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  input.value = project.name;
  input.disabled = project.archived;
  button.disabled = project.archived;
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    alert.hidden = true;
    if (!input.value.trim()) {
      showError(alert, 'Project name is required');
      return;
    }
    button.disabled = true;
    try {
      Object.assign(project, await request(`/api/projects/${project.id}/name`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      }));
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      input.value = project.name;
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = project.archived;
    }
  });
  app.append(section);
}

async function renderTasks(project) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Tasks');
  section.innerHTML = `
    <div class="task-filter">
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority">
        <option value="Low">Low</option>
        <option value="Normal">Normal</option>
        <option value="High">High</option>
      </select>
    </div>
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="completed">Completed</option>
      </select>
    </div>
    <div class="task-filter">
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter">
        <option value="all">All</option>
        <option value="Low">Low</option>
        <option value="Normal">Normal</option>
        <option value="High">High</option>
      </select>
    </div>
    <form id="due-range">
      <label for="due-from">Due from</label>
      <input id="due-from" type="text" placeholder="YYYY-MM-DD" autocomplete="off">
      <label for="due-through">Due through</label>
      <div class="create-controls">
        <input id="due-through" type="text" placeholder="YYYY-MM-DD" autocomplete="off">
        <button type="submit">Apply due range</button>
      </div>
    </form>
    <form id="task-search-form" class="search-form">
      <label for="task-search">Task search</label>
      <div class="create-controls">
        <input id="task-search" type="text" autocomplete="off">
        <button type="submit">Search tasks</button>
      </div>
    </form>
    <div id="tasks"></div>
  `;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  const filter = section.querySelector('#task-filter');
  const priorityFilter = section.querySelector('#priority-filter');
  const dueRangeForm = section.querySelector('#due-range');
  const dueFrom = section.querySelector('#due-from');
  const dueThrough = section.querySelector('#due-through');
  // Draft inputs only replace the applied range after successful validation.
  let dueRange = { from: '', through: '' };
  const searchForm = section.querySelector('#task-search-form');
  const searchInput = section.querySelector('#task-search');
  let searchQuery = '';
  const defaultPriority = section.querySelector('#default-task-priority');
  defaultPriority.value = project.default_task_priority;
  defaultPriority.disabled = project.archived;
  defaultPriority.addEventListener('change', async () => {
    defaultPriority.disabled = true;
    button.disabled = true;
    alert.hidden = true;
    try {
      Object.assign(project, await request(`/api/projects/${project.id}/default-task-priority`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority: defaultPriority.value }),
      }));
    } catch (error) {
      showError(alert, error.message);
    } finally {
      defaultPriority.value = project.default_task_priority;
      defaultPriority.disabled = project.archived;
      button.disabled = project.archived;
    }
  });
  const list = section.querySelector('#tasks');
  const endpoint = `/api/projects/${project.id}/tasks`;
  let tasks = [];
  let destinations = [];

  function displayTasks() {
    list.replaceChildren();
    for (const task of filterTasks(tasks, filter.value, priorityFilter.value, dueRange, searchQuery)) {
      const row = document.createElement('div');
      row.dataset.testid = 'task-row';
      row.className = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        alert.hidden = true;
        try {
          const updated = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, updated);
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(alert, error.message);
        } finally {
          checkbox.disabled = project.archived;
        }
      });
      const renameForm = document.createElement('form');
      renameForm.className = 'task-rename';
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      renameLabel.textContent = 'New task title';
      const renameInput = document.createElement('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.type = 'text';
      renameInput.autocomplete = 'off';
      renameInput.value = task.title;
      renameInput.disabled = project.archived;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameButton.disabled = project.archived;
      const renameControls = document.createElement('div');
      renameControls.className = 'create-controls';
      renameControls.append(renameInput, renameButton);
      renameForm.append(renameLabel, renameControls);
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (project.archived) return;
