    ['', '2024-02-29', [2, 3, 4]],
    ['2024-03-01', '2024-12-31', []],
    ['', '0001-01-01', [2]],
    ['9999-12-31', '', [6]],
  ];
  for (const [from, through, ids] of ranges) {
