/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('public/app.js')
s=p.read_text().replace('<option value=\"completed\">Completed</option>', '<option value=\"completed\">Completed</option>\\n        <option value=\"deleted\">Deleted</option>')
start=s.index('  function displayTasks()')
end=s.index(\"\\n  filter.addEventListener\",start)
chunk=s[start:end].replace('project.archived','cannotEdit')
chunk=chunk.replace(\"      const row = document.createElement('div');\", \"      const cannotEdit = project.archived || task.deleted;\\n      const row = document.createElement('div');\")
chunk=chunk.replace('      row.append(title, checkbox, priorityControls, renameForm, dueDateForm, notesForm, moveForm);', '''      const deletionButton = document.createElement('button');
      deletionButton.type = 'button';
      deletionButton.textContent = task.deleted ? 'Restore task' : 'Delete task';
      deletionButton.disabled = project.archived;
      deletionButton.addEventListener('click', async () => {
        if (project.archived) return;
        alert.hidden = true;
        deletionButton.disabled = true;
        try {
          Object.assign(task, await request("'`${endpoint}/${task.id}/deleted`, {
            method: '"'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ deleted: "'!task.deleted }),
          }));
          displayTasks();
        } catch (error) {
          showError(alert, error.message);
        } finally {
          deletionButton.disabled = project.archived;
        }
      });
      row.append(title, checkbox, priorityControls, renameForm, dueDateForm, notesForm, moveForm, deletionButton);'"''')
s=s[:start]+chunk+s[end:]
p.write_text(s)
p=Path('test/migration.test.js')
s=p.read_text().replace(\"notes: ''\", \"notes: '', deleted: false\")
p.write_text(s)
p=Path('README.md')
s=p.read_text().replace('All/Open/Completed filters', 'All/Open/Completed/Deleted filters').replace('counts across all its tasks.', 'counts across all its live tasks.').replace('and archive state.', 'deletion state, and archive state.')
s+='''\\nLive task rows provide Delete task. Deletion preserves every saved field, ownership, and remembered position while excluding the task from All/Open/Completed and project summaries. The Deleted filter intersects priority, due range, and title search; deleted rows show disabled editing and move controls. Restore task in an active project returns the task to its reserved position without changing fields or resetting filters. Archived projects allow reading deleted tasks but disable deletion and restoration. Deletion persists across restarts; upgrades initialize existing tasks as live.\\n'''
p.write_text(s)
PY
npm test"

